17-06.avif" width="412" height="512" class="image-carousel__image" alt="" loading="lazy" style="display:none;"><!--]--></div><div class="carousel-autoplay carousel-autoplay--paused image-carousel__controls" style="--autoplay-item-duration:5000ms;"><button class="carousel-autoplay__button" aria-label="Play carousel"><svg xmlns="http://www.w3.org/2000/svg" width="40" height="40" viewBox="0 0 40 40"><g><path fill="currentColor" d="M16 14.741a1 1 0 0 1 1.504-.864l9.015 5.26a1 1 0 0 1 0 1.727l-9.015 5.259A1 1 0 0 1 16 25.259z"></path></g></svg></button><div class="carousel-autoplay__dots"><!--[--><button class="carousel-autoplay__dot--active carousel-autoplay__dot" aria-label="Go to slide 1"></button><button class="carousel-autoplay__dot" aria-label="Go to slide 2"></button><button class="carousel-autoplay__dot" aria-label="Go to slide 3"></button><button class="carousel-autoplay__dot" aria-label="Go to slide 4"></button><button class="carousel-autoplay__dot" aria-label="Go to slide 5"></button><button class="carousel-autoplay__dot" aria-label="Go to slide 6"></button><!--]--></div></div></div><!--]--></div><div class="image-info-box__item image-info-box__item--main"><div class="scroll-box"><div class="vertical-scroll-progress-bar vertical-scroll-progress-bar--theme-primary scroll-box__progress-bar"></div><div class="scroll-box__header"><p class="u-text-body-large">У нас ты получишь не только лечение и идеальную улыбку, но и заботу, открытость и поддержку на протяжении всего пути к результату. Наша миссия — изменить представление о стоматологии.</p><!----></div><div class="scroll-box__body"><!--[--><!--[--><div class="u-wysiwyg"><p>Музыка, атмосфера и изысканный интерьер, а также специально созданная среда позволят тебе ощутить совершенно иной вид стоматологического лечения — комфортный, умиротворяющий и вдохновляющий.</p>
<p>Мы хотим, чтобы твои впечатления от сотрудничества с нами были как от полета первым классом — персональные, комфортные и без каких-либо забот и стресса.</p>
</div><!--]--><!--]--></div></div></div><!----></div><!--]--></div></div><!--]--></div><div class="overlay-section"><!--[--><div class="about-experience u-bg-primary"><div class="wheel-block"><div class="wheel-block__sticky-content"><div class="wheel-block__header"><div class="container container--size-default"><!--[--><h2 class="section-title u-text-headings-large"><!--[-->Твоя улыбка начинается здесь<!--]--></h2><!--]--></div></div><div class="wheel-block__body"><div class="wheel-block__body-inner"><div class="container container--size-default"><!--[--><div class="wheel-block-wheel"><svg xmlns="http://www.w3.org/2000/svg" width="1202" height="1202" viewBox="0 0 1202 1202" fill="none" class="wheel-block-wheel__svg" style="--wheel-rotation-degrees-start:60deg;"><circle cx="600" cy="600" r="534.5" stroke="#DDEFDE" opacity=".2"></circle><!--[--><g class="wheel-step" transform="rotate(0 600 600)"><circle class="wheel-step__dot" cx="600" cy="65.5" r="5"></circle><circle class="wheel-step__bubble" cx="600" cy="20" r="20"></circle><text class="wheel-step__text" x="600" y="20" text-anchor="middle" alignment-baseline="central">1</text><path class="wheel-step__line" d="M601 90v116"></path></g><g class="wheel-step" transform="rotate(60 600 600)"><circle class="wheel-step__dot" cx="600" cy="65.5" r="5"></circle><circle class="wheel-step__bubble" cx="600" cy="20" r="20"></circle><text class="wheel-step__text" x="600" y="20" text-anchor="middle" alignment-baseline="central">2</text><path class="wheel-step__line" d="M601 90v116"></path></g><g class="wheel-step" transform="rotate(120 600 600)"><circle class="wheel-step__dot" cx="600" cy="65.5" r="5"></circle><circle class="wheel-step__bubble" cx="600" cy="20" r="20"></circle><text class="wheel-step__text" x="600" y="20" text-anchor="middle" alignment-baseline="central">3</text><path class="wheel-step__line" d="M601 90v116"></path></g><g class="wheel-step" transform="rotate(180 600 600)"><circle class="wheel-step__dot" cx="600" cy="65.5" r="5"></circle><circle class="wheel-step__bubble" cx="600" cy="20" r="20"></circle><text class="wheel-step__text" x="600" y="20" text-anchor="middle" alignment-baseline="central">4</text><path class="wheel-step__line" d="M601 90v116"></path></g><g class="wheel-step" transform="rotate(240 600 600)"><circle class="wheel-step__dot" cx="600" cy="65.5" r="5"></circle><circle class="wheel-step__bubble" cx="600" cy="20" r="20"></circle><text class="wheel-step__text" x="600" y="20" text-anchor="middle" alignment-baseline="central">5</text><path class="wheel-step__line" d="M601 90v116"></path></g><g class="wheel-step" transform="rotate(300 600 600)"><circle class="wheel-step__dot" cx="600" cy="65.5" r="5"></circle><circle class="wheel-step__bubble" cx="600" cy="20" r="20"></circle><text class="wheel-step__text" x="600" y="20" text-anchor="middle" alignment-baseline="central">6</text><path class="wheel-step__line" d="M601 90v116"></path></g><!--]--></svg><!--[--><div class="wheel-block-wheel__item"><h3 class="u-text-headings-small wheel-block-wheel__item-title">Более личное, чем личное</h3><p class="u-text-body-medium wheel-block-wheel__item-description">После комплексной диагностики каждому пациенту назначается координатор плана лечения, или персональный консьерж. Консьерж обеспечивает безупречность и индивидуальный подход на протяжении всего процесса — от планирования визитов до мельчайших деталей, которые сделают твой опыт приятным и спокойным.</p></div><div class="wheel-block-wheel__item"><h3 class="u-text-headings-small wheel-block-wheel__item-title">Результат, который ты можешь увидеть заранее</h3><p class="u-text-body-medium wheel-block-wheel__item-description">Мы создаём 3D-цифровой дизайн улыбки ещё до начала лечения. Ты не только знаешь, каким будет конечный результат, но и видишь его, можешь на него повлиять и быть уверенными в каждом следующем шаге.</p></div><div class="wheel-block-wheel__item"><h3 class="u-text-headings-small wheel-block-wheel__item-title">Спокойствие и безопасность при каждом визите</h3><p class="u-text-body-medium wheel-block-wheel__item-description">Мы верим, что лечение начинается с чувств. Свет, дизайн интерьера, тишина и доброжелательное отношение нашей команды создают атмосферу, в которой ты сможешь освободиться от стресса и забыть о прежнем восприятии стоматологии как неприятного опыта.</p></div><div class="wheel-block-wheel__item"><h3 class="u-text-headings-small wheel-block-wheel__item-title">С кино – в кресле для процедур</h3><p class="u-text-body-medium wheel-block-wheel__item-description">Время, проведенное в кресле, станет приятным — выбери любимый фильм, сериал или обучающий контент и позволь лечению протекать незаметно.</p></div><div class="wheel-block-wheel__item"><h3 class="u-text-headings-small wheel-block-wheel__item-title">Все в одном месте</h3><p class="u-text-body-medium wheel-block-wheel__item-description">Для нас важно, что ты экономишь не только деньги, но и время и энергию. Терапевт, протезист, эндодонтист, имплантолог, специалист по эстетике и гигиенист — все в одном месте, в клинике LAVA dental. Это означает более быстрый, точный и эффективный процесс лечения.</p></div><div class="wheel-block-wheel__item"><h3 class="u-text-headings-small wheel-block-wheel__item-title">Полная конфиденциальность</h3><p class="u-text-body-medium wheel-block-wheel__item-description">Лечение проходит в тихих, закрытых помещениях, а не в открытых зонах. Здесь ты можешь чувствовать себя в безопасности, свободно и комфортно, без посторонних взглядов и помех.</p></div><!--]--></div><!--]--></div></div></div></div><div class="wheel-block__triggers"><!--[--><div data-nr="1" class="wheel-block__trigger"></div><div data-nr="2" class="wheel-block__trigger"></div><div data-nr="3" class="wheel-block__trigger"></div><div data-nr="4" class="wheel-block__trigger"></div><div data-nr="5" class="wheel-block__trigger"></div><div data-nr="6" class="wheel-block__trigger"></div><!--]--></div></div></div><!--]--></div><div class="overlay-section"><!--[--><div class="reveal-block about-apply"><div class="reveal-block__content"><div class="reveal-block__header u-bg-secondary"><div class="container container--size-default"><!--[--><p class="reveal-block__title u-text-headings-large"><span class="word" aria-hidden="true" style="display: inline-block;">Это</span> <span class="word" aria-hidden="true" style="display: inline-block;">мы</span> <span class="word" aria-hidden="true" style="display: inline-block;">—</span> <span class="word" aria-hidden="true" style="display: inline-block;">LAVA</span> <span class="word" aria-hidden="true" style="display: inline-block;">dental</span> <span class="word" aria-hidden="true" style="display: inline-block;">studio.</span><span class="sr-only" style="position: absolute; width: 1px; height: 1px; padding: 0px; margin: -1px; overflow: hidden; clip: rect(0px, 0px, 0px, 0px); white-space: nowrap; border: 0px;">Это мы — LAVA dental studio.</span></p><!--]--></div></div><div class="u-bg-primary reveal-block__body" style=""><div class="reveal-block__bg"><canvas class="lava-bg-illustration reveal-block__bg-illustration" width="1920" height="1230"></canvas><div class="container container--size-default"><!--[--><p class="reveal-block__title reveal-block__title--bg u-text-headings-large">Это мы — LAVA dental studio.</p><!--]--></div></div><div class="container container--size-default"><!--[--><div class="reveal-block__main-wrap"><div class="reveal-block__main"><!--[--><div class="about-apply-grid"><div class="about-apply-grid__item about-apply-box u-bg-secondary"><div class="about-apply-box__aside"><div class="video-dialog video-dialog--type-cover about-apply-box__preview"><video class="video-dialog__preview" width="300" height="534" muted="" loop="" playsinline="" src="/cms/api/media/file/about-preview.webm" autoplay=""></video><button aria-label="Play video" class="video-dialog__button"><div class="icon-button icon-button--type-primary icon-button--size-medium video-dialog__play-button"><div class="icon-button__icon"><!--[--><svg xmlns="http://www.w3.org/2000/svg" width="54" height="54" viewBox="0 0 54 54"><path fill="currentColor" d="M22.031 19.687a1 1 0 0 1 1.515-.858l12.188 7.313a1 1 0 0 1 0 1.715L23.546 35.17a1 1 0 0 1-1.515-.857V19.687Z"></path></svg><!--]--></div></div></button><!--teleport start--><!--teleport end--></div></div><div class="about-apply-box__body"><p class="u-text-headings-small">Запишись на прием и сделай шаг к своей идеальной улыбке!</p><a class="button button--type-secondary button--icon-end about-apply-box__cta-button" href="https://booking.lavadental.lv/ru" target="_blank"><div class="button__text u-text-body-button"><!--[-->Записаться на приём<!--]--></div><!----></a></div></div></div><!--]--></div></div><!--]--></div></div></div><div class="reveal-block__timeline"><div class="reveal-block__timeline-item reveal-block__timeline-item--intro"></div><div class="reveal-block__timeline-item reveal-block__timeline-item--main"></div></div></div><!--]--></div></section>
