services-list-item-grid"><!--[--><div class="services-list-item-grid__item service-list-item" style="--delay:0s;"><div class="service-list-item__nr u-text-body-large">06</div><h3 class="service-list-item__title u-text-headings-small">Седация и наркоз</h3><div class="service-list-item__action"><div class="icon-button icon-button--type-primary icon-button--size-medium link-button service-list-item__link"><div class="icon-button__icon"><!--[--><svg xmlns="http://www.w3.org/2000/svg" width="60" height="60" viewBox="0 0 60 60"><path fill="#031C14" d="M36.657 24.343a1 1 0 0 0-1-1h-9a1 1 0 0 0 0 2h8v8a1 1 0 1 0 2 0v-9ZM24.344 35.656l.707.707L36.365 25.05l-.708-.707-.707-.708L23.637 34.95l.707.707Z"></path></svg><!--]--></div></div></div></div><div class="services-list-item-grid__item service-list-item" style="--delay:0.3s;"><div class="service-list-item__nr u-text-body-large">07</div><h3 class="service-list-item__title u-text-headings-small">Терапия</h3><div class="service-list-item__action"><div class="icon-button icon-button--type-primary icon-button--size-medium link-button service-list-item__link"><div class="icon-button__icon"><!--[--><svg xmlns="http://www.w3.org/2000/svg" width="60" height="60" viewBox="0 0 60 60"><path fill="#031C14" d="M36.657 24.343a1 1 0 0 0-1-1h-9a1 1 0 0 0 0 2h8v8a1 1 0 1 0 2 0v-9ZM24.344 35.656l.707.707L36.365 25.05l-.708-.707-.707-.708L23.637 34.95l.707.707Z"></path></svg><!--]--></div></div></div></div><div class="services-list-item-grid__item service-list-item" style="--delay:0.6s;"><div class="service-list-item__nr u-text-body-large">08</div><h3 class="service-list-item__title u-text-headings-small">Эндодонтия</h3><div class="service-list-item__action"><div class="icon-button icon-button--type-primary icon-button--size-medium link-button service-list-item__link"><div class="icon-button__icon"><!--[--><svg xmlns="http://www.w3.org/2000/svg" width="60" height="60" viewBox="0 0 60 60"><path fill="#031C14" d="M36.657 24.343a1 1 0 0 0-1-1h-9a1 1 0 0 0 0 2h8v8a1 1 0 1 0 2 0v-9ZM24.344 35.656l.707.707L36.365 25.05l-.708-.707-.707-.708L23.637 34.95l.707.707Z"></path></svg><!--]--></div></div></div></div><div class="services-list-item-grid__item service-list-item" style="--delay:0.8999999999999999s;"><div class="service-list-item__nr u-text-body-large">09</div><h3 class="service-list-item__title u-text-headings-small">Хирургия</h3><div class="service-list-item__action"><div class="icon-button icon-button--type-primary icon-button--size-medium link-button service-list-item__link"><div class="icon-button__icon"><!--[--><svg xmlns="http://www.w3.org/2000/svg" width="60" height="60" viewBox="0 0 60 60"><path fill="#031C14" d="M36.657 24.343a1 1 0 0 0-1-1h-9a1 1 0 0 0 0 2h8v8a1 1 0 1 0 2 0v-9ZM24.344 35.656l.707.707L36.365 25.05l-.708-.707-.707-.708L23.637 34.95l.707.707Z"></path></svg><!--]--></div></div></div></div><div class="services-list-item-grid__item service-list-item" style="--delay:1.2s;"><div class="service-list-item__nr u-text-body-large">10</div><h3 class="service-list-item__title u-text-headings-small">Элайнеры</h3><div class="service-list-item__action"><div class="icon-button icon-button--type-primary icon-button--size-medium link-button service-list-item__link"><div class="icon-button__icon"><!--[--><svg xmlns="http://www.w3.org/2000/svg" width="60" height="60" viewBox="0 0 60 60"><path fill="#031C14" d="M36.657 24.343a1 1 0 0 0-1-1h-9a1 1 0 0 0 0 2h8v8a1 1 0 1 0 2 0v-9ZM24.344 35.656l.707.707L36.365 25.05l-.708-.707-.707-.708L23.637 34.95l.707.707Z"></path></svg><!--]--></div></div></div></div><!--]--></div><!--]--></div></div></div></div></section>
<section id="team" style="view-timeline:--tl-section-team;"><div class="overlay-section"><div class="team doctor-profile u-bg-secondary"><div class="container container--size-default"><div class="doctor-profile__header"><p class="doctor-profile__eyebrow u-text-body-xsmall">Знакомьтесь с врачом</p><h2 class="u-text-headings-large">Стоматология, которой можно доверять.</h2></div><div class="doctor-profile__grid"><div class="doctor-profile__portrait"><div class="doctor-profile__portrait-frame" role="img" aria-label="Временное изображение доктора Крити Шриваставы"><span class="doctor-profile__initials" aria-hidden="true">KS</span><span class="doctor-profile__portrait-note" aria-hidden="true">Временное изображение</span></div></div><article class="doctor-profile__content"><p class="doctor-profile__eyebrow u-text-body-xsmall">Ваш стоматолог в Нашике</p><h3 class="doctor-profile__name">Доктор Крити Шривастава</h3><p class="doctor-profile__role u-text-body-large">Главный стоматолог-хирург</p><p class="doctor-profile__reg u-text-body-xsmall">Регистрационный номер 1977</p><div class="doctor-profile__body u-text-body-medium"><p>Доктор Крити Шривастава возглавляет Shrivastava Dental Clinic и сочетает внимательный подход с точной диагностикой и понятным планом лечения.</p><p>Она выслушивает ваши опасения, понятно объясняет каждый этап и использует современную диагностику и бережные методики, чтобы каждый визит был спокойным и предсказуемым.</p></div><ul class="doctor-profile__facts"><li class="doctor-profile__chip u-text-body-xsmall">Индивидуальный подход</li><li class="doctor-profile__chip u-text-body-xsmall">Бережные методики</li><li class="doctor-profile__chip u-text-body-xsmall">Современная диагностика</li></ul><div class="doctor-profile__actions"><a class="button button--type-primary" href="tel:7796376170"><div class="button__text u-text-body-button">Записаться на приём</div></a><a class="doctor-profile__link u-text-body-button" href="#services">Услуги</a></div></article></div></div></div></div></section><section id="pricing" style="view-timeline:--tl-section-pricing;"><div class="pricing u-bg-secondary"><div class="container container--size-default"><!--[--><div class="pricing__header"><h2 class="u-text-headings-large">Прайс-лист — инвестиция в твою улыбку</h2></div><div class="pricing__body"><div class="u-wysiwyg"><h3>Инвестиции в улыбку с прозрачной стоимостью.</h3>
<p>В LAVA Dental Studio мы уверены, что прозрачная стоимость возможна только после тщательной диагностики и планирования лечения. Поэтому сначала мы проведём для тебя комплексное обследование, после чего наши стоматологи составят для тебя индивидуальный план лечения, который позволит достичь твоих целей и желаний.</p>
</div><div class="pricing__items"><div class="tabs pricing-items__tabs"><div class="tabs__labels"><!--[--><button class="tabs__label--active tabs__label u-text-body-medium">Комплексная диагностика</button><button class="tabs__label u-text-body-medium">Гигиена зубов и полости рта</button><button class="tabs__label u-text-body-medium">Восстановление и терапия зубов</button><button class="tabs__label u-text-body-medium">Эстетика и коррекция</button><!--]--></div><div class="tabs__content"><div><!--[--><div class="pricing-items"><!--[--><div class="pricing-item"><div class="pricing-item__header"><h3 class="pricing-item__title u-text-headings-medium">Комплексная диагностика — «Идеальная улыбка» </h3><p class="pricing-item__price u-text-headings-medium">280€ </p></div><div class="pricing-item__body u-wysiwyg"><div class="payload-richtext"><ul class="list-bullet"><li class="" style="text-align: left;" value="1">Полная проверка полости рта и зубов</li><li class="" style="text-align: left;" value="2">Интраоральное сканирование с помощью инновационных сканеров 3Shape и iTero Lumina&nbsp;</li><li class="" style="text-align: left;" value="3">Цифровая рентгенография зубов и 3D компьютерная томография&nbsp;</li><li class="" style="text-align: left;" value="4">Цифровой дизайн улыбки (DSD)&nbsp;—&nbsp;ты видишь свою будущую улыбку до начала лечения</li><li class="" style="text-align: left;" value="5">Индивидуальный план лечения с конкретными сроками, стоимостью и прогнозом</li><li class="" style="text-align: left;" value="6">Персональный координатор плана лечения, который заботится о твоем комфорте на протяжении всего процесса</li></ul></div></div></div><!--]--></div><!--]--></div></div></div></div></div><div class="pricing__footer"><p class="pricing__notice u-text-body-medium">Цены на услуги варьируются в зависимости от различных факторов, включая тип и сложность процедуры.</p></div><!--]--></div></div></section>
<section id="faq" style="view-timeline:--tl-section-faq;"><div class="faq u-bg-secondary"><div class="container container--size-default"><!--[--><div class="faq__header"><h2 class="u-text-headings-large">Прежде чем начать, вам, возможно, захочется узнать больше.</h2></div><div class="faq__body"><div class="faq-categories"><!--[--><details class="details details--size-large faq-category" open="" style="--delay:0s;"><summary class="details__header" style=""><div class="u-text-headings-small details__title">Диагностика и лечение</div><svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36" class="details__marker"><path class="details__marker-line-plus" fill="currentColor" d="M16.5 5h3v24h-3V5Z"></path><path class="details__marker-line-minus" fill="currentColor" d="M30 15.5v3H6v-3h24Z"></path></svg></summary><div class="details__body"><!--[--><div class="faq-items"><!--[--><details class="details details--size-small faq-item" open="" style="--delay:0s;"><summary class="details__header" style=""><div class="u-text-body-large details__title">Сколько времени занимает первый визит на комплексную диагностику?</div><svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36" class="details__marker"><path class="details__marker-line-plus" fill="currentColor" d="M16.5 5h3v24h-3V5Z"></path><path class="details__marker-line-minus" fill="currentColor" d="M30 15.5v3H6v-3h24Z"></path></svg></summary><div class="details__body"><!--[--><div class="u-wysiwyg"><div class="payload-richtext"><p>Первый визит длится около 30 минут.<br>Второй визит — презентация плана лечения — до 30 минут.<br>Если вы живете за пределами Латвии или часто путешествуете, презентационный визит можно провести удаленно (на платформе Zoom), в свою очередь мы поможем компактно спланировать визиты на лечение.</p></div></div><!--]--></div></details><details class="details details--size-small faq-item" style="--delay:0.1s;"><summary class="details__header" style=""><div class="u-text-body-large details__title">Какие исследования проводятся во время комплексной диагностики?</div><svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36" class="details__marker"><path class="details__marker-line-plus" fill="currentColor" d="M16.5 5h3v24h-3V5Z"></path><path class="details__marker-line-minus" fill="currentColor" d="M30 15.5v3H6v-3h24Z"></path></svg></summary><div class="details__body"><!--[--><div class="u-wysiwyg"><div class="payload-richtext"><ul class="list-bullet"><li class="" style="" value="1">Визуальный осмотр полости рта и зубов</li><li class="" style="" value="2">Цифровые рентгенограммы</li><li class="" style="" value="3">Интраоральное 3D-сканирование (3Shape, iTero Lumina)</li><li class="" style="" value="4">3D компьютерная томография&nbsp;(KSDT)</li><li class="" style="" value="5">Диагностический фотопротокол</li></ul></div></div><!--]--></div></details><details class="details details--size-small faq-item" style="--delay:0.2s;"><summary class="details__header" style=""><div class="u-text-body-large details__title">Что такое DSD — цифровой дизайн улыбки?</div><svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36" class="details__marker"><path class="details__marker-line-plus" fill="currentColor" d="M16.5 5h3v24h-3V5Z"></path><path class="details__marker-line-minus" fill="currentColor" d="M30 15.5v3H6v-3h24Z"></path></svg></summary><div class="details__body"><!--[--><div class="u-wysiwyg"><div class="payload-richtext"><p>DSD — это метод, позволяющий увидеть конечный результат ещё до начала лечения. Он помогает подобрать идеальную форму и пропорции улыбки, которые подчеркнут твою индивидуальность, гармонично впишутся в черты лица и позволят тебе чувствовать себя более уверенным.</p></div></div><!--]--></div></details><details class="details details--size-small faq-item" style="--delay:0.30000000000000004s;"><summary class="details__header" style=""><div class="u-text-body-large details__title">Сколько времени занимает разработка плана лечения?</div><svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36" class="details__marker"><path class="details__marker-line-plus" fill="currentColor" d="M16.5 5h3v24h-3V5Z"></path><path class="details__marker-line-minus" fill="currentColor" d="M30 15.5v3H6v-3h24Z"></path></svg></summary><div class="details__body"><!--[--><div class="u-wysiwyg"><div class="payload-richtext"><p>В среднем 5 дней. Точная продолжительность зависит от состояния твоей полости рта и целей лечения.</p></div></div><!--]--></div></details><details class="details details--size-small faq-item" style="--delay:0.4s;"><summary class="details__header" style=""><div class="u-text-body-large details__title">Кто такой координатор плана лечения?</div><svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36" class="details__marker"><path class="details__marker-line-plus" fill="currentColor" d="M16.5 5h3v24h-3V5Z"></path><path class="details__marker-line-minus" fill="currentColor" d="M30 15.5v3H6v-3h24Z"></path></svg></summary><div class="details__body"><!--[--><div class="u-wysiwyg"><div class="payload-richtext"><p style="text-align: left;">Это специалист, который заботится о прозрачности и удобстве всего процесса лечения.</p><p style="text-align: left;">Координатор помогает:</p><ul class="list-bullet"><li class="" style="text-align: left;" value="1">понять план лечения и стоимость</li><li class="" style="text-align: left;" value="2">согласовать время приёма</li><li class="" style="text-align: left;" value="3">ответить на практические вопросы</li><li class="" style="text-align: left;" value="4">дать тебе возможность сосредоточиться только на самом важном — на своем здоровье и улыбке</li></ul></div></div><!--]--></div></details><details class="details details--size-small faq-item" style="--delay:0.5s;"><summary class="details__header" style=""><div class="u-text-body-large details__title">Можно ли получить данные своего обследования?</div><svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36" class="details__marker"><path class="details__marker-line-plus" fill="currentColor" d="M16.5 5h3v24h-3V5Z"></path><path class="details__marker-line-minus" fill="currentColor" d="M30 15.5v3H6v-3h24Z"></path></svg></summary><div class="details__body"><!--[--><div class="u-wysiwyg"><div class="payload-richtext"><p>Да, мы отправляем цифровые рентгеновские снимки по электронной почте. Передача интраоральных снимков технически невозможна.</p></div></div><!--]--></div></details><details class="details details--size-small faq-item" style="--delay:0.6000000000000001s;"><summary class="details__header" style=""><div class="u-text-body-large details__title">Можно ли получить план лечения в распечатанном виде?</div><svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36" class="details__marker"><path class="details__marker-line-plus" fill="currentColor" d="M16.5 5h3v24h-3V5Z"></path><path class="details__marker-line-minus" fill="currentColor" d="M30 15.5v3H6v-3h24Z"></path></svg></summary><div class="details__body"><!--[--><div class="u-wysiwyg"><div class="payload-richtext"><p>Да, после разработки плана ты получишь его финансовую часть в распечатанном виде.</p></div></div><!--]--></div></details><!--]--></div><!--]--></div></details><details class="details details--size-large faq-category" style="--delay:0.1s;"><summary class="details__header" style=""><div class="u-text-headings-small details__title">Услуги и цены</div><svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36" class="details__marker"><path class="details__marker-line-plus" fill="currentColor" d="M16.5 5h3v24h-3V5Z"></path><path class="details__marker-line-minus" fill="currentColor" d="M30 15.5v3H6v-3h24Z"></path></svg></summary><div class="details__body"><!--[--><div class="faq-items"><!--[--><details class="details details--size-small faq-item" style="--delay:0s;"><summary class="details__header" style=""><div class="u-text-body-large details__title">Сколько стоят ваши услуги?</div><svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36" class="details__marker"><path class="details__marker-line-plus" fill="currentColor" d="M16.5 5h3v24h-3V5Z"></path><path class="details__marker-line-minus" fill="currentColor" d="M30 15.5v3H6v-3h24Z"></path></svg></summary><div class="details__body"><!--[--><div class="u-wysiwyg"><div class="payload-richtext"><p>Цены зависят от типа и сложности процедуры. Точная стоимость определяется только после комплексной диагностики. Стоимость наиболее популярных услуг представлена ​​в нашем&nbsp;<strong>прайс-листе</strong>.</p></div></div><!--]--></div></details><details class="details details--size-small faq-item" style="--delay:0.1s;"><summary class="details__header" style=""><div class="u-text-body-large details__title">Какие решения вы предлагаете?</div><svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36" class="details__marker"><path class="details__marker-line-plus" fill="currentColor" d="M16.5 5h3v24h-3V5Z"></path><path class="details__marker-line-minus" fill="currentColor" d="M30 15.5v3H6v-3h24Z"></path></svg></summary><div class="details__body"><!--[--><div class="u-wysiwyg"><div class="payload-richtext"><ul class="list-bullet"><li class="" style="text-align: left;" value="1">Эксклюзивные виниры</li><li class="" style="text-align: left;" value="2">Зубные имплантаты (Straumann, Neodent)</li><li class="" style="text-align: left;" value="3">Элайнеры (прозрачные капы)</li><li class="" style="text-align: left;" value="4">Решения All-ON-X в случае потери нескольких зубов</li><li class="" style="text-align: left;" value="5">Профессиональная гигиена и отбеливание (система FLASH)</li><li class="" style="text-align: left;" value="6">Эстетическая и терапевтическая стоматология</li><li class="" style="text-align: left;" value="7">Эндодонтия (лечение корневых каналов под контролем микроскопа)</li><li class="" style="" value="8">Стоматологическая хирургия</li></ul></div></div><!--]--></div></details><details class="details details--size-small faq-item" style="--delay:0.2s;"><summary class="details__header" style=""><div class="u-text-body-large details__title">Что такое All-ON-X?</div><svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36" class="details__marker"><path class="details__marker-line-plus" fill="currentColor" d="M16.5 5h3v24h-3V5Z"></path><path class="details__marker-line-minus" fill="currentColor" d="M30 15.5v3H6v-3h24Z"></path></svg></summary><div class="details__body"><!--[--><div class="u-wysiwyg"><div class="payload-richtext"><p style="text-align: left;">All-ON-X — уникальный метод, который обеспечивает:</p><ul class="list-bullet"><li class="" style="text-align: left;" value="1">Удаление поврежденных зубов во время одной операции</li><li class="" style="text-align: left;" value="2">Установка 4 или 6 имплантатов</li><li class="" style="text-align: left;" value="3">Сразу устанавливается несъемный протез (immediate loading, немедленная нагрузка)<br>Процедура обычно проводится под седацией — ты&nbsp;<strong>просто засыпаешь и просыпаешься с новой улыбкой.&nbsp;</strong>Идеально подходит для пациентов с множественной потерей зубов или нуждающихся в полном протезировании.</li></ul></div></div><!--]--></div></details><!--]--></div><!--]--></div></details><details class="details details--size-large faq-category" style="--delay:0.2s;"><summary class="details__header" style=""><div class="u-text-headings-small details__title">Комфорт и безопасность</div><svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36" class="details__marker"><path class="details__marker-line-plus" fill="currentColor" d="M16.5 5h3v24h-3V5Z"></path><path class="details__marker-line-minus" fill="currentColor" d="M30 15.5v3H6v-3h24Z"></path></svg></summary><div class="details__body"><!--[--><div class="faq-items"><!--[--><details class="details details--size-small faq-item" style="--delay:0s;"><summary class="details__header" style=""><div class="u-text-body-large details__title">Возможно ли лечение без страха и дискомфорта?</div><svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36" class="details__marker"><path class="details__marker-line-plus" fill="currentColor" d="M16.5 5h3v24h-3V5Z"></path><path class="details__marker-line-minus" fill="currentColor" d="M30 15.5v3H6v-3h24Z"></path></svg></summary><div class="details__body"><!--[--><div class="u-wysiwyg"><div class="payload-richtext"><p>Да, мы предлагаем лечение с седацией или общим наркозом. Наш ведущий анестезиолог обеспечит безопасность и комфорт, чтобы чувство спокойствия и уверенности не покидало тебя.</p></div></div><!--]--></div></details><details class="details details--size-small faq-item" style="--delay:0.1s;"><summary class="details__header" style=""><div class="u-text-body-large details__title">Является ли гигиена полости рта болезненной процедурой?</div><svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36" class="details__marker"><path class="details__marker-line-plus" fill="currentColor" d="M16.5 5h3v24h-3V5Z"></path><path class="details__marker-line-minus" fill="currentColor" d="M30 15.5v3H6v-3h24Z"></path></svg></summary><div class="details__body"><!--[--><div class="u-wysiwyg"><div class="payload-richtext"><p>Нет. Мы используем новейшую технологию —&nbsp;<strong>EMS AIRFLOW® Prophylaxis Master</strong>. Это безопасный, точный и комфортный метод удаления зубного налёта, пигментов и зубного камня без повреждения тканей зуба.</p></div></div><!--]--></div></details><!--]--></div><!--]--></div></details><details class="details details--size-large faq-category" style="--delay:0.30000000000000004s;"><summary class="details__header" style=""><div class="u-text-headings-small details__title">О клинике</div><svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36" class="details__marker"><path class="details__marker-line-plus" fill="currentColor" d="M16.5 5h3v24h-3V5Z"></path><path class="details__marker-line-minus" fill="currentColor" d="M30 15.5v3H6v-3h24Z"></path></svg></summary><div class="details__body"><!--[--><div class="faq-items"><!--[--><details class="details details--size-small faq-item" style="--delay:0s;"><summary class="details__header" style=""><div class="u-text-body-large details__title">Почему вы называетесь студией, а не клиникой?</div><svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36" class="details__marker"><path class="details__marker-line-plus" fill="currentColor" d="M16.5 5h3v24h-3V5Z"></path><path class="details__marker-line-minus" fill="currentColor" d="M30 15.5v3H6v-3h24Z"></path></svg></summary><div class="details__body"><!--[--><div class="u-wysiwyg"><div class="payload-richtext"><p>Мы хотим изменить представление о стоматологии. Студия — это современное, красивое и уютное пространство с умиротворяющей атмосферой. Здесь улыбка создаётся как произведение искусства — с помощью науки, технологий и заботы о человеке.</p></div></div><!--]--></div></details><details class="details details--size-small faq-item" style="--delay:0.1s;"><summary class="details__header" style=""><div class="u-text-body-large details__title">Где находится LAVA Dental Studio?</div><svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36" class="details__marker"><path class="details__marker-line-plus" fill="currentColor" d="M16.5 5h3v24h-3V5Z"></path><path class="details__marker-line-minus" fill="currentColor" d="M30 15.5v3H6v-3h24Z"></path></svg></summary><div class="details__body"><!--[--><div class="u-wysiwyg"><div class="payload-richtext"><p>Ты найдешь нас в Риге, на улице Аусекля, 14 (1 этаж). Доступна парковка в зоне B, которую мы оплачиваем, пока ты находишься в нашей студии.</p></div></div><!--]--></div></details><details class="details details--size-small faq-item" style="--delay:0.2s;"><summary class="details__header" style=""><div class="u-text-body-large details__title">Есть ли парковка для клиентов?</div><svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36" class="details__marker"><path class="details__marker-line-plus" fill="currentColor" d="M16.5 5h3v24h-3V5Z"></path><path class="details__marker-line-minus" fill="currentColor" d="M30 15.5v3H6v-3h24Z"></path></svg></summary><div class="details__body"><!--[--><div class="u-wysiwyg"><div class="payload-richtext"><p>У нас нет собственной парковки, но мы платим за парковочное место в соседней зоне B. Просто сообщи об этом нашей команде.</p></div></div><!--]--></div></details><!--]--></div><!--]--></div></details><!--]--></div></div><!--]--></div></div></section>
<section id="contacts" style="view-timeline:--tl-section-contacts;"><div class="contacts u-bg-secondary"><div class="container container--size-default"><!--[--><div class="contacts__header"><h2 class="u-text-headings-large">Мы здесь </h2></div><div class="contacts__body"><div class="image-info-box"><div class="image-info-box__item image-info-box__item--aside"><!--[--><img width="740" height="627" data-nuxt-img="" srcset="/assets/img/1de9caf9aa9f-map.svg 1x, /assets/img/dd2271325196-map.svg 2x" onerror="this.setAttribute('data-error', 1)" class="image image-info-box__image" alt="Map" loading="lazy" src="/assets/img/1de9caf9aa9f-map.svg"><!--]--></div><div class="image-info-box__item image-info-box__item--main"><div class="scroll-box"><div class="vertical-scroll-progress-bar vertical-scroll-progress-bar--theme-primary scroll-box__progress-bar"></div><div class="scroll-box__header"><p class="u-text-body-large">Удобное расположение сделает твой визит ещё проще. С лёгким доступом для людей с ограниченной мобильностью.</p><!----></div><div class="scroll-box__body"><!--[--><!--[--><div class="u-wysiwyg"><p>Наша студия находится по адресу ул. Аусекля, 14, где есть парковочные места в зоне B. Мы оплатим твою парковку во время твоего пребывания в клинике LAVA dental.</p>
</div><!--]--><!--]--></div></div></div><!----></div></div><div class="contacts__footer"><img width="1290" height="590" data-nuxt-img="" sizes="(max-width: 639px) 100vw, (max-width: 1279px) 100vw, (max-width: 1349px) 100vw, 1290px" srcset="/assets/img/6be9b9a04821-location.avif 320w, /assets/img/936863dc2c1a-location.avif 640w, /assets/img/9f7348037191-location.avif 1280w, /assets/img/99bea6f7b10f-location.avif 1290w, /assets/img/4bbb139df2cb-location.avif 2560w, /assets/img/b86bd4d1f5a0-location.avif 2580w" onerror="this.setAttribute('data-error', 1)" class="image" alt="LAVA Dental Studio" loading="lazy" src="/assets/img/b86bd4d1f5a0-location.avif"></div><!--]--></div></div></section><!--]--></div></main>
